(lib.User_Names = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.stop();
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Txt
	this.text = new cjs.Text("", "49px 'ONEMobilePOPRegular'", "#511F17");
	this.text.textAlign = "center";
	this.text.lineHeight = 63;
	this.text.lineWidth = 131;
	this.text.parent = this;
	this.text.setTransform(449.15,79.8);

	this.timeline.addTween(cjs.Tween.get(this.text).wait(1));

	// img
	this.instance = new lib.Am01_Temps_img41();
	this.instance.setTransform(322.75,73.15);

	this.timeline.addTween(cjs.Tween.get(this.instance).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.User_Names, new cjs.Rectangle(322.8,73.2,247.99999999999994,121.39999999999999), null);


